// Import/export the standard Netscape bookmark HTML format (research.md #7).
import { parse } from 'node-html-parser';

// Parse a Netscape bookmark file into { address, title, tags[] } entries.
// Nested <H3> folder names become tags on the contained bookmarks (FR-020).
export function parseNetscape(html) {
  const root = parse(html || '', { blockTextElements: {} });
  const entries = [];

  // Walk the DOM tracking the folder (<H3>) stack. In the Netscape format a
  // <DT> contains either an <H3> (folder heading, whose <DL> follows) or an <A>.
  function walk(node, folders) {
    for (const child of node.childNodes) {
      if (child.nodeType !== 1) continue; // elements only
      const tag = child.rawTagName ? child.rawTagName.toUpperCase() : '';
      if (tag === 'DL') {
        walk(child, folders);
      } else if (tag === 'DT') {
        const heading = child.querySelector('h3');
        const anchor = child.querySelector('a');
        if (heading) {
          const folderName = heading.text.trim();
          const nextFolders = folderName ? [...folders, folderName] : folders;
          // The folder's <DL> is a sibling <DL> inside this same <DT> or following it.
          const innerDl = child.querySelector('dl');
          if (innerDl) walk(innerDl, nextFolders);
          // Some exports place the <DL> as a sibling after the <DT>.
          let sib = child.nextElementSibling;
          if (sib && sib.rawTagName && sib.rawTagName.toUpperCase() === 'DL') {
            walk(sib, nextFolders);
          }
        } else if (anchor) {
          const href = anchor.getAttribute('href');
          if (href) {
            entries.push({
              address: href.trim(),
              title: anchor.text.trim(),
              tags: [...folders],
            });
          }
        }
      } else {
        walk(child, folders);
      }
    }
  }

  walk(root, []);
  return entries;
}

function escapeHtml(s) {
  return String(s || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

// Generate a Netscape bookmark HTML document from bookmark objects.
// Each bookmark's tags are emitted as TAGS="a,b" (browser-compatible) so that a
// round-trip preserves them (FR-021/SC-008).
export function generateNetscape(bookmarks) {
  const lines = [
    '<!DOCTYPE NETSCAPE-Bookmark-file-1>',
    '<META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8">',
    '<TITLE>Bookmarks</TITLE>',
    '<H1>Bookmarks</H1>',
    '<DL><p>',
  ];
  for (const b of bookmarks) {
    const added = Math.floor(new Date(b.createdAt || Date.now()).getTime() / 1000);
    const tagsAttr = b.tags && b.tags.length ? ` TAGS="${escapeHtml(b.tags.join(','))}"` : '';
    lines.push(
      `    <DT><A HREF="${escapeHtml(b.address)}" ADD_DATE="${added}"${tagsAttr}>${escapeHtml(
        b.title || b.address
      )}</A>`
    );
  }
  lines.push('</DL><p>');
  return lines.join('\n') + '\n';
}

