:root {
  --bg: #f5f6f8;
  --card: #ffffff;
  --ink: #1c2330;
  --muted: #6b7280;
  --line: #e3e6eb;
  --brand: #2563eb;
  --brand-ink: #ffffff;
  --danger: #dc2626;
  --radius: 12px;
  --shadow: 0 1px 3px rgba(16, 24, 40, 0.08), 0 1px 2px rgba(16, 24, 40, 0.06);
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--ink);
}

.app { max-width: 960px; margin: 0 auto; padding: 20px 16px 64px; }

.topbar {
  display: flex; flex-wrap: wrap; gap: 12px; align-items: center;
  margin-bottom: 12px;
}
.brand { font-size: 22px; margin: 0; flex: 0 0 auto; }
.add-form { display: flex; gap: 8px; flex: 1 1 320px; }
.add-form input {
  flex: 1; padding: 10px 12px; border: 1px solid var(--line);
  border-radius: 10px; font-size: 15px; background: var(--card);
}
.porting { display: flex; gap: 8px; }

button, .btn-secondary, .btn-primary, .btn-danger {
  cursor: pointer; font-size: 14px; border-radius: 10px; border: 1px solid var(--line);
  padding: 10px 14px; background: var(--card); color: var(--ink); text-decoration: none;
  display: inline-flex; align-items: center;
}
#add-btn, .btn-primary { background: var(--brand); color: var(--brand-ink); border-color: var(--brand); }
.btn-danger { color: var(--danger); border-color: #f3c9c9; }
button:hover { filter: brightness(0.97); }

.add-error {
  background: #fdecec; color: var(--danger); border: 1px solid #f3c9c9;
  padding: 10px 12px; border-radius: 10px; margin-bottom: 12px; font-size: 14px;
}

.views { display: flex; gap: 6px; margin: 8px 0 14px; }
.view-tab { background: transparent; border: none; padding: 8px 14px; border-radius: 999px; color: var(--muted); }
.view-tab.active { background: var(--ink); color: #fff; }

.toolbar { display: flex; gap: 8px; margin-bottom: 16px; flex-wrap: wrap; }
.toolbar input, .toolbar select {
  padding: 9px 12px; border: 1px solid var(--line); border-radius: 10px;
  background: var(--card); font-size: 14px;
}
.toolbar input[type="search"] { flex: 1 1 200px; }

.list { display: grid; gap: 12px; }

.card {
  display: flex; gap: 14px; background: var(--card); border: 1px solid var(--line);
  border-radius: var(--radius); padding: 14px; box-shadow: var(--shadow); cursor: pointer;
  transition: transform 0.05s ease;
}
.card:hover { transform: translateY(-1px); }
.card-thumb {
  width: 96px; height: 72px; flex: 0 0 auto; border-radius: 8px; object-fit: cover;
  background: #eef1f5; border: 1px solid var(--line);
}
.card-thumb.placeholder { display: flex; align-items: center; justify-content: center; font-size: 26px; color: #c3c9d2; }
.card-body { flex: 1; min-width: 0; }
.card-head { display: flex; align-items: center; gap: 8px; }
.card-favicon { width: 16px; height: 16px; flex: 0 0 auto; border-radius: 3px; }
.card-title { font-weight: 600; font-size: 16px; margin: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.card-url { color: var(--muted); font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; margin: 2px 0 6px; }
.card-desc { color: #4b5563; font-size: 13px; margin: 0 0 8px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.card-meta { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.tag { background: #eef2ff; color: #3949ab; font-size: 12px; padding: 2px 8px; border-radius: 999px; }
.badge-unread { background: #fff4e5; color: #b45309; font-size: 12px; padding: 2px 8px; border-radius: 999px; font-weight: 600; }

.empty { text-align: center; color: var(--muted); padding: 60px 20px; font-size: 15px; }

.overlay { position: fixed; inset: 0; background: rgba(17, 24, 39, 0.45); display: flex; align-items: flex-start; justify-content: center; padding: 40px 16px; overflow-y: auto; }
.panel { background: var(--card); border-radius: 16px; padding: 22px; width: 100%; max-width: 560px; position: relative; box-shadow: 0 20px 40px rgba(0,0,0,0.2); }
.panel-close { position: absolute; top: 12px; right: 12px; border: none; background: transparent; font-size: 24px; line-height: 1; padding: 4px 8px; }
.panel-notice { background: #eef2ff; color: #3949ab; padding: 8px 12px; border-radius: 8px; margin-bottom: 12px; font-size: 14px; }
.panel-preview { width: 100%; max-height: 200px; object-fit: cover; border-radius: 10px; margin-bottom: 12px; border: 1px solid var(--line); }
.panel-title { margin: 0 0 4px; font-size: 18px; }
.panel-link { color: var(--brand); font-size: 13px; word-break: break-all; display: block; margin-bottom: 14px; }
.field-label { display: block; font-size: 12px; font-weight: 600; color: var(--muted); text-transform: uppercase; letter-spacing: 0.03em; margin: 10px 0 4px; }
.panel input, .panel textarea { width: 100%; padding: 9px 11px; border: 1px solid var(--line); border-radius: 9px; font-size: 14px; font-family: inherit; }
.snapshot-row { margin: 14px 0 4px; font-size: 14px; }
.snapshot-row a { color: var(--brand); }
.snapshot-none { color: var(--muted); }
.panel-actions { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 18px; }
.panel-actions .btn-danger { margin-left: auto; }

